    summary:
      "2026 年 11 月 7 日，第九届进博会配套活动「『人工智能+交通运输』上海发布 2026」在国家会展中心举行，《上海市「人工智能+交通运输」创新应用行动方案》正式对外发布。方案对标国家「人工智能+交通运输」实施意见与上海「模塑申城」战略，从核心要素供给、场景创新应用、建设发展机制、保障措施四个维度给出任务与路径，覆盖港口航运、机场民航、轨道交通、道路交通、自动驾驶、邮政物流、政务服务。技术侧要筑牢三个底座：交通大模型与智能体、高质量行业数据集、算力集群，算力依托长三角国家算力枢纽。落地的重点项目点名四个：Mass 一体化出行、隧道群数字孪生、港口集疏运无人化、交通政务智能服务；同时要搭交通可信数据空间，并强调算法全链条安全防护。同场揭牌与启动两个平台：交通大模型创新与产业联盟长三角区域协同中心揭牌，秘书处落在上海；航运物流枢纽人工智能中试基地启动建设，由上港集团联合产学研做「1331X」能力体系，围绕港内装卸、集疏运、多式联运三个场景做中试验证，官方口径是基础设施已基本建成、已纳管 54 个业务智能体。会上还有同济、上海交大、上海海事三校联合发布高校成果，上海市交通委分别与中国移动上海公司、中国电信上海分公司、上海库帕思科技签约。交通运输部与 20 个省市交通主管部门到场，规模约 300 名代表。",
