    title: "工信部给智能体终端定进网规矩：预置 AI 助手的手机要在检测里过适配，App 可以电子签名拒绝被调用",
    summary:
      "工信部 11 月 6 日 08:44 在官网挂出《关于加强智能体终端设备进网管理的通知》（工信厅信管〔2026〕42 号，文末落款 2026 年 10 月 24 日，来源信息通信管理局）。适用对象是「预置安装智能体的手机、平板、可穿戴设备等电信终端」。四项任务：一是智能体开发者要与终端做适配验证，在产品设置页公示已完成适配的终端型号与操作系统，上架应用商店前先向分发平台提交适配情况；二是预置智能体的终端在进网检测中须依标准做适配验证，并做涉诈风险安全评估与反诈能力前置评测，终端上的智能体应参考智能体互联系列国家标准配备唯一身份码，终端拿到进网许可证前后要保持一致，发生重大变化须报备并重新检测；三是走 OTA 给现网设备升级智能体的，先提交升级方案（时间、规模、用户群体、业务场景、服务内容、经营模式、网络与数据安全措施、反诈措施），升级结束后提交报告，经工信部组织专家评估、征求意见后方可正式向用户提供服务；四是分发环节，应用开发者通过电子签名主动声明是否同意智能体调用，未声明同意的智能体不得强制调用调取应用，分发页须公示适配验证列表、不得给不兼容机型提供下载，平台要巡查并对未完成适配的智能体限期整改或下架。通知未写施行日期与过渡期。",
