    summary:
      "字节跳动旗下智能体开发平台扣子（Coze）发布《扣子企业版下线公告》，分三段执行：企业标准版与企业旗舰版自 2026 年 11 月 30 日起停止接受新客户购买；2026 年 12 月 31 日起，通过火山引擎购买的旧个人进阶版、旧企业版、旧团队版全面下线，超期未使用的部分自动退还至客户火山引擎账户；2027 年 12 月 31 日，新版企业标准版与企业旗舰版也全面下线。现有客户仍可续费或增购席位，但服务到期日不得晚于 2027 年 12 月 31 日；官方建议仍要用旧版套餐的客户先退订、再买新版企业套餐。下线理由官方只给了四个字「产品整合安排」，面向企业客户的全新产品形态与配套方案称「仍在规划中，另行公布」。组织上的铺垫更早：2026 年 7 月底飞书产品团队与豆包团队整合，8 月 24 日 TRAE 与扣子团队整体并入豆包体系，8 月 25 日字节发布独立 AI 办公产品「豆包工作」，CEO 梁汝波在全员会上提出「高度优先，粗主干，优化长期」。商业数据给出另一层解释：IDC《2025 中国智能体开发平台市场份额报告》显示扣子以 19.3% 的份额居公有云市场第一，但该市场 2025 年全年规模仅约 2.5 亿元，按此折算扣子的平台收入不到五千万元。对把业务搭在扣子企业版上的团队来说，迁移成本从现在开始显性化。",
