    title: "发改委 11 月 3 日发布会：AI 要立基础性综合性法律，还要建「监管沙盒」，模型训练师、数据标注员拟进国家职业分类",
    summary:
      "11 月 3 日上午，国家发展改革委举行「奋进『十五五』」系列新闻发布会，创新和高技术发展司副司长王若蒙、国家数据局政策和规划司司长栾婕出席，AI 治理口径集中在这一场。立法上明确「加快推进人工智能基础性综合性立法」，构建法律法规体系的「四梁八柱」，同时补齐数据、算力、算法等共性要素与重点应用场景的立法，建立覆盖全生命周期的安全标准和伦理准则，并对制度实施情况做周期性评估、动态调整。监管上提出「寓监管于服务」：合理设置过渡期、明确透明可预期的执行标准，支持建设面向不同领域的人工智能「监管沙盒」，同步健全申请、测试、使用、退出机制并预置风险缓冲。落地上继续「点线面」推进——点上优先挑矿山开采、高空作业、应急救灾这类「险、脏、累、繁、难」场景做应用攻关，线上推制造、能源、交通、医疗等国家人工智能应用中试基地，面上细化重点行业实施方案。社会影响两块最具体：就业侧推动「模型训练师」「数据标注员」等新职业纳入国家职业分类体系，并对替代风险做监测预警；权益侧针对算法歧视、深度伪造、隐私泄露增强溯源能力，对老年人、未成年人单列保护。国际合作方面称世界人工智能合作组织已有 38 国作为创始成员国加入，正推动实体化运行。同场国家数据局谈数据要素：研究出台公共数据资源开发利用责任制政策文件、探索公共数据授权运营收益分配机制，加强高质量数据集建设、深化数据标注先行先试。",
