    id: "openai-rosalind-academic-plan",
    title: "OpenAI 推出 Rosalind Academic Plan：给美国高校学术实验室最多 30 个免费 Business Standard 席位、最长 12 个月，含生命科学专用模型 GPT-Rosalind（不含 API）",
